import{f as a,o as l,c as i,ah as e}from"./chunks/framework.5bt9HFMa.js";const r="/assets/%E8%BF%87%E7%A8%8B%E6%B5%81.gtYaZcJI.png",o="/assets/%E7%80%91%E5%B8%83%E6%B5%81.Cb6rxb6D.png",s="/assets/%E5%8E%9F%E5%9E%8B%E5%BC%80%E5%8F%91%E8%8C%83%E5%9E%8B.DAujf-yC.png",n="/assets/%E5%85%B8%E5%9E%8B%E7%9A%84%E8%9E%BA%E6%97%8B%E6%A8%A1%E5%9E%8B.BlsphUqC.png",h="/assets/%E7%BB%9F%E4%B8%80%E8%BF%87%E7%A8%8B.PDhWGDEs.png",d="/assets/%E6%9E%81%E9%99%90%E7%BC%96%E7%A8%8B.D7A_1pM5.png",g="/assets/%E4%BB%8E%E9%9C%80%E6%B1%82%E6%A8%A1%E5%9E%8B%E5%88%B0%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%9E%8B%E7%9A%84%E8%BD%AC%E6%8D%A2.C3-4fy1I.png",c="/assets/%E7%94%A8%E6%88%B7%E4%BA%A4%E4%BA%92%E8%BF%87%E7%A8%8B%E8%AE%BE%E8%AE%A1.BZZtbJn1.png",u="/assets/McCall._4P5H6VA.png",p="/assets/%E6%B5%8B%E8%AF%95%E7%AD%96%E7%95%A5.BfmrGcao.png",b="/assets/%E6%B5%8B%E8%AF%95%E6%AD%A5%E9%AA%A4.wH7PVOQZ.png",B=JSON.parse('{"title":"软件工程复习笔记","description":"软件工程复习笔记，涵盖软件过程、敏捷开发、需求工程、设计、测试等。","frontmatter":{"title":"软件工程复习笔记","date":"2025-12-09T00:00:00.000Z","description":"软件工程复习笔记，涵盖软件过程、敏捷开发、需求工程、设计、测试等。","outline":2,"prev":{"text":"第六章 行为型设计模式","link":"/series/软件设计体系结构/06-行为型设计模式"}},"headers":[],"relativePath":"series/软件设计体系结构/note.md","filePath":"series/软件设计体系结构/note.md","lastUpdated":1777391754000}'),q={name:"series/软件设计体系结构/note.md"};function x(f,t,m,E,P,k){return l(),i("div",null,t[0]||(t[0]=[e('<h1 id="软件工程复习笔记" tabindex="-1">软件工程复习笔记 <a class="header-anchor" href="#软件工程复习笔记" aria-label="Permalink to &quot;软件工程复习笔记&quot;">​</a></h1><h2 id="软件的定义" tabindex="-1">软件的定义 <a class="header-anchor" href="#软件的定义" aria-label="Permalink to &quot;软件的定义&quot;">​</a></h2><p>软件包含三个方面：</p><ol><li><strong>指令的集合</strong>（计算机程序）：通过执行这些指令可以满足预期的特性、功能和性能需求</li><li><strong>数据结构</strong>：使得程序可以合理利用信息</li><li><strong>软件描述信息</strong>：以硬拷贝和虚拟形式存在，用来描述程序的操作和使用</li></ol><h2 id="遗留软件中的问题" tabindex="-1">遗留软件中的问题 <a class="header-anchor" href="#遗留软件中的问题" aria-label="Permalink to &quot;遗留软件中的问题&quot;">​</a></h2><p>遗留软件通常具有以下特点（质量差）：</p><ul><li>数不清的问题</li><li>系统设计难以扩展</li><li>代码令人费解</li><li>文档混乱甚至根本没有</li><li>测试用例和结果并未归档</li><li>变更的历史管理混乱</li></ul><h2 id="软件工程的定义" tabindex="-1">软件工程的定义 <a class="header-anchor" href="#软件工程的定义" aria-label="Permalink to &quot;软件工程的定义&quot;">​</a></h2><p>将系统化的、规范的、可量化的方法应用于软件的开发、运行和维护，即将工程化方法应用于软件。</p><h2 id="软件工程层次图" tabindex="-1">软件工程层次图 <a class="header-anchor" href="#软件工程层次图" aria-label="Permalink to &quot;软件工程层次图&quot;">​</a></h2><ul><li>工具</li><li>方法</li><li>过程</li><li>质量关注点</li></ul><h2 id="软件过程" tabindex="-1">软件过程 <a class="header-anchor" href="#软件过程" aria-label="Permalink to &quot;软件过程&quot;">​</a></h2><p>是工作产品构建时所执行的一系列活动、动作和任务的集合。</p><h2 id="软件工程过程框架" tabindex="-1">软件工程过程框架 <a class="header-anchor" href="#软件工程过程框架" aria-label="Permalink to &quot;软件工程过程框架&quot;">​</a></h2><p>通常包含以下 5 个活动：</p><ol><li>沟通</li><li>策划</li><li>建模</li><li>构建</li><li>部署</li></ol><h2 id="典型的普适性活动" tabindex="-1">典型的普适性活动 <a class="header-anchor" href="#典型的普适性活动" aria-label="Permalink to &quot;典型的普适性活动&quot;">​</a></h2><ul><li>软件项目跟踪和控制</li><li>风险管理</li><li>软件质量保证</li><li>技术评审</li><li>测量</li><li>软件配置管理</li><li>可复用性管理</li><li>工作产品的准备和生产</li></ul><h2 id="过程流" tabindex="-1">过程流 <a class="header-anchor" href="#过程流" aria-label="Permalink to &quot;过程流&quot;">​</a></h2><p>过程流描述了在执行顺序和执行时间上如何组织框架中的活动、动作和任务。</p><p><img src="'+r+'" alt="alt text"></p><h2 id="惯用过程模型" tabindex="-1">惯用过程模型 <a class="header-anchor" href="#惯用过程模型" aria-label="Permalink to &quot;惯用过程模型&quot;">​</a></h2><p>惯用过程模型定义一组预定义的过程元素和一个可预测的过程工作流。惯用过程模型力求达到软件开发的结构和秩序，其活动和任务都是按照过程的特定指引顺序进行的。</p><h3 id="瀑布流模型" tabindex="-1">瀑布流模型 <a class="header-anchor" href="#瀑布流模型" aria-label="Permalink to &quot;瀑布流模型&quot;">​</a></h3><p><img src="'+o+'" alt="alt text"></p><h3 id="原型开发范型" tabindex="-1">原型开发范型 <a class="header-anchor" href="#原型开发范型" aria-label="Permalink to &quot;原型开发范型&quot;">​</a></h3><p><img src="'+s+'" alt="alt text"></p><h3 id="螺旋模型" tabindex="-1">螺旋模型 <a class="header-anchor" href="#螺旋模型" aria-label="Permalink to &quot;螺旋模型&quot;">​</a></h3><p><img src="'+n+'" alt="alt text"></p><h3 id="统一过程-unified-process-up" tabindex="-1">统一过程 (Unified Process, UP) <a class="header-anchor" href="#统一过程-unified-process-up" aria-label="Permalink to &quot;统一过程 (Unified Process, UP)&quot;">​</a></h3><p>统一过程尝试着从传统的软件过程中挖掘最好的特征和性质，但是以敏捷软件开发中许多最好的原则来实现。</p><p><strong>UML (Unified Modeling Language)</strong>：统一建模语言，包含了大批用于面向对象系统建模和开发的符号。</p><p><img src="'+h+'" alt="alt text"></p><h2 id="敏捷软件开发" tabindex="-1">敏捷软件开发 <a class="header-anchor" href="#敏捷软件开发" aria-label="Permalink to &quot;敏捷软件开发&quot;">​</a></h2><h3 id="敏捷宣言" tabindex="-1">敏捷宣言 <a class="header-anchor" href="#敏捷宣言" aria-label="Permalink to &quot;敏捷宣言&quot;">​</a></h3><p>他们主张：</p><ul><li><strong>个人和他们之间的交流</strong> 胜过 开发过程和工具</li><li><strong>可运行的软件</strong> 胜过 宽泛的文档</li><li><strong>客户合作</strong> 胜过 合同谈判</li><li><strong>对变更的良好响应</strong> 胜过 按部就班地遵循计划</li></ul><h3 id="极限编程-xp" tabindex="-1">极限编程 (XP) <a class="header-anchor" href="#极限编程-xp" aria-label="Permalink to &quot;极限编程 (XP)&quot;">​</a></h3><p>极限编程包括策划、设计、编码和测试四个框架活动的规则和实践。</p><p><img src="'+d+'" alt="alt text"></p><h3 id="敏捷过程模型-vs-螺旋模型" tabindex="-1">敏捷过程模型 vs 螺旋模型 <a class="header-anchor" href="#敏捷过程模型-vs-螺旋模型" aria-label="Permalink to &quot;敏捷过程模型 vs 螺旋模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">敏捷过程模型</th><th style="text-align:left;">螺旋模型</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>适用性</strong></td><td style="text-align:left;">不适合大型高风险或任务关键型项目</td><td style="text-align:left;">不适用于小型、低风险的项目</td></tr><tr><td style="text-align:left;"><strong>文档与规则</strong></td><td style="text-align:left;">最少化规则、最少化文档</td><td style="text-align:left;">需要多个步骤，以及前期完成的文档</td></tr><tr><td style="text-align:left;"><strong>测试人员</strong></td><td style="text-align:left;">测试人员需要持续参与</td><td style="text-align:left;">测试人员的早期参与（可由外部团队完成）</td></tr><tr><td style="text-align:left;"><strong>变更适应</strong></td><td style="text-align:left;">易于适应产品变更</td><td style="text-align:left;">在原型完成前难以进行产品更改</td></tr><tr><td style="text-align:left;"><strong>利益相关者</strong></td><td style="text-align:left;">非常依赖利益相关者的交互</td><td style="text-align:left;">需要利益相关者持续参与计划和风险评估</td></tr><tr><td style="text-align:left;"><strong>管理</strong></td><td style="text-align:left;">易于管理</td><td style="text-align:left;">需要正式的项目管理和协调</td></tr><tr><td style="text-align:left;"><strong>交付</strong></td><td style="text-align:left;">尽早交付部分解决方案</td><td style="text-align:left;">难以判断项目结束时间</td></tr><tr><td style="text-align:left;"><strong>风险管理</strong></td><td style="text-align:left;">非正式的风险管理</td><td style="text-align:left;">良好的风险管理</td></tr><tr><td style="text-align:left;"><strong>过程改进</strong></td><td style="text-align:left;">内建的持续过程改进</td><td style="text-align:left;">项目结束时进行过程改进</td></tr></tbody></table><h2 id="团队管理" tabindex="-1">团队管理 <a class="header-anchor" href="#团队管理" aria-label="Permalink to &quot;团队管理&quot;">​</a></h2><h3 id="高效的团队" tabindex="-1">高效的团队 <a class="header-anchor" href="#高效的团队" aria-label="Permalink to &quot;高效的团队&quot;">​</a></h3><p>高效的团队必须建立：</p><ul><li><strong>目标意识</strong></li><li><strong>参与意识</strong>：让每个成员都能感受到自己的技能得到了发挥，所做出的贡献是有价值的。</li><li><strong>信任意识</strong>：团队中的软件工程师应该相信同伴和其管理者的技术与能力。</li><li><strong>进步意识</strong>：定期审视软件工程方法并寻求改善途径。</li></ul><h3 id="有害团队环境的因素" tabindex="-1">有害团队环境的因素 <a class="header-anchor" href="#有害团队环境的因素" aria-label="Permalink to &quot;有害团队环境的因素&quot;">​</a></h3><ol><li>混乱的工作氛围</li><li>会造成团队成员分裂的挫败</li><li>“支离破碎或协调不当”的软件过程</li><li>对软件团队中角色的模糊定义</li><li>“持续且重复性的失败”</li></ol><h2 id="需求工程" tabindex="-1">需求工程 <a class="header-anchor" href="#需求工程" aria-label="Permalink to &quot;需求工程&quot;">​</a></h2><p>需求工程包括七项任务：</p><ol><li>起始</li><li>获取</li><li>细化</li><li>协商</li><li>规格说明</li><li>确认</li><li>管理</li></ol><h3 id="规格说明" tabindex="-1">规格说明 <a class="header-anchor" href="#规格说明" aria-label="Permalink to &quot;规格说明&quot;">​</a></h3><p>规格说明可以是一份写好的文档、一套图形化的模型、一个形式化的数学模型、一组使用场景、一个原型或上述各项的任意组合。</p><h3 id="分析模型的元素" tabindex="-1">分析模型的元素 <a class="header-anchor" href="#分析模型的元素" aria-label="Permalink to &quot;分析模型的元素&quot;">​</a></h3><ul><li>基于场景的元素</li><li>基于类的元素</li><li>基于流的元素</li><li>基于行为的元素</li></ul><h3 id="需求模型的目标" tabindex="-1">需求模型的目标 <a class="header-anchor" href="#需求模型的目标" aria-label="Permalink to &quot;需求模型的目标&quot;">​</a></h3><ol><li>描述客户需要什么</li><li>为软件设计奠定基础</li><li>定义在软件完成后可以被确认的一组需求</li></ol><h3 id="crc-建模" tabindex="-1">CRC 建模 <a class="header-anchor" href="#crc-建模" aria-label="Permalink to &quot;CRC 建模&quot;">​</a></h3><p>类－职责－协作者 (Class-Responsibility-Collaborator, CRC) 建模提供了一个简单方法，可以识别和组织与系统或产品需求相关的类。</p><p><img src="'+g+'" alt="alt text"></p><h2 id="设计概念" tabindex="-1">设计概念 <a class="header-anchor" href="#设计概念" aria-label="Permalink to &quot;设计概念&quot;">​</a></h2><p><strong>信息隐蔽</strong>：通过定义一系列独立的模块得到有效的模块化，独立模块之间只交流实现软件功能所必需的信息。</p><h3 id="组织良好的设计类的特征" tabindex="-1">组织良好的设计类的特征 <a class="header-anchor" href="#组织良好的设计类的特征" aria-label="Permalink to &quot;组织良好的设计类的特征&quot;">​</a></h3><ul><li><strong>完整性与充分性</strong></li><li><strong>原始性</strong></li><li><strong>高内聚性</strong></li><li><strong>低耦合性</strong></li></ul><h2 id="体系结构设计" tabindex="-1">体系结构设计 <a class="header-anchor" href="#体系结构设计" aria-label="Permalink to &quot;体系结构设计&quot;">​</a></h2><p><strong>定义</strong>：软件体系结构定义了一个系统的“结构元素和其相应的接口”以及系统中各个构件和子系统的“行为”。体系结构设计的目的是创建系统和软件的“内聚的，规划良好的表示”。</p><h3 id="体系结构模型的来源" tabindex="-1">体系结构模型的来源 <a class="header-anchor" href="#体系结构模型的来源" aria-label="Permalink to &quot;体系结构模型的来源&quot;">​</a></h3><ol><li>关于将要构建的软件的应用域信息</li><li>特定的需求模型元素（如用例或分析类、现有问题中它们的关系和协作）</li><li>可获得的体系结构风格和模式</li></ol><h3 id="接口设计的三个重要元素" tabindex="-1">接口设计的三个重要元素 <a class="header-anchor" href="#接口设计的三个重要元素" aria-label="Permalink to &quot;接口设计的三个重要元素&quot;">​</a></h3><ol><li><strong>用户界面 (UI)</strong></li><li><strong>外部接口</strong>：和其他系统、设备、网络、信息生成者或使用者的接口</li><li><strong>内部接口</strong>：各种设计构件之间的接口</li></ol><h3 id="体系结构风格" tabindex="-1">体系结构风格 <a class="header-anchor" href="#体系结构风格" aria-label="Permalink to &quot;体系结构风格&quot;">​</a></h3><ul><li>以数据为中心的体系结构</li><li>数据流体系结构</li><li>调用和返回体系结构</li><li>面向对象体系结构</li><li>层次体系结构</li></ul><h2 id="构件级设计" tabindex="-1">构件级设计 <a class="header-anchor" href="#构件级设计" aria-label="Permalink to &quot;构件级设计&quot;">​</a></h2><p><strong>工作产品</strong>：每个构件的设计都以图形、表格或基于文本的表示法表示。</p><h3 id="构件的观点" tabindex="-1">构件的观点 <a class="header-anchor" href="#构件的观点" aria-label="Permalink to &quot;构件的观点&quot;">​</a></h3><ul><li><strong>面向对象的观点</strong>：一个构件包括一个协作类集合。构件中的每个类都得到详细阐述，以包括所有属性和与其实现相关的操作。</li><li><strong>传统的观点</strong>：一个构件就是程序的一个功能要素，程序由处理逻辑、实现处理逻辑所需的内部数据结构以及能够保证构件被调用和实现数据传递的接口构成。</li></ul><h3 id="构件级设计原则" tabindex="-1">构件级设计原则 <a class="header-anchor" href="#构件级设计原则" aria-label="Permalink to &quot;构件级设计原则&quot;">​</a></h3><ol><li><strong>开闭原则 (OCP)</strong></li><li><strong>里氏替换原则 (LSP)</strong></li><li><strong>依赖倒置原则 (DIP)</strong></li><li><strong>接口隔离原则 (ISP)</strong></li></ol><h3 id="打包原则" tabindex="-1">打包原则 <a class="header-anchor" href="#打包原则" aria-label="Permalink to &quot;打包原则&quot;">​</a></h3><ul><li>发布／复用等价性原则</li><li>共同封装原则</li><li>共同复用原则</li></ul><h3 id="内聚与耦合" tabindex="-1">内聚与耦合 <a class="header-anchor" href="#内聚与耦合" aria-label="Permalink to &quot;内聚与耦合&quot;">​</a></h3><ul><li><strong>内聚性</strong>：功能内聚、分层内聚、通信内聚等。</li><li><strong>耦合性</strong>：类之间彼此联系程度的一种定性度量。</li></ul><h2 id="用户界面设计" tabindex="-1">用户界面设计 <a class="header-anchor" href="#用户界面设计" aria-label="Permalink to &quot;用户界面设计&quot;">​</a></h2><h3 id="黄金规则" tabindex="-1">黄金规则 <a class="header-anchor" href="#黄金规则" aria-label="Permalink to &quot;黄金规则&quot;">​</a></h3><ol><li>把控制权交给用户</li><li>减轻用户的记忆负担</li><li>保持界面一致</li></ol><h3 id="界面分析与设计的四种模型" tabindex="-1">界面分析与设计的四种模型 <a class="header-anchor" href="#界面分析与设计的四种模型" aria-label="Permalink to &quot;界面分析与设计的四种模型&quot;">​</a></h3><ol><li><strong>用户模型</strong>：由工程师建立</li><li><strong>设计模型</strong>：由软件工程师创建</li><li><strong>用户的心理模型（系统感觉）</strong>：最终用户在脑海里对界面的印象</li><li><strong>实现模型</strong>：由系统实现者创建</li></ol><h3 id="用户交互过程设计" tabindex="-1">用户交互过程设计 <a class="header-anchor" href="#用户交互过程设计" aria-label="Permalink to &quot;用户交互过程设计&quot;">​</a></h3><p><img src="'+c+'" alt="alt text"></p><h2 id="软件质量" tabindex="-1">软件质量 <a class="header-anchor" href="#软件质量" aria-label="Permalink to &quot;软件质量&quot;">​</a></h2><p><strong>定义</strong>：在一定程度上应用有效的软件过程，创造有用的产品，为生产者和使用者提供明显的价值。</p><h3 id="mccall-的软件质量因素" tabindex="-1">McCall 的软件质量因素 <a class="header-anchor" href="#mccall-的软件质量因素" aria-label="Permalink to &quot;McCall 的软件质量因素&quot;">​</a></h3><p><img src="'+u+'" alt="alt text"></p><h3 id="质量困境" tabindex="-1">质量困境 <a class="header-anchor" href="#质量困境" aria-label="Permalink to &quot;质量困境&quot;">​</a></h3><p>如果生产了一个存在严重质量问题的软件系统，将受到损失。另一方面，如果花费无限的时间和成本开发绝对完美的软件，可能会错失市场机会或耗尽资源。企业界努力达到中间状态：产品足够好不会被抛弃，又不需要花费太长时间和太多成本。</p><h3 id="质量成本" tabindex="-1">质量成本 <a class="header-anchor" href="#质量成本" aria-label="Permalink to &quot;质量成本&quot;">​</a></h3><ul><li><strong>预防成本</strong></li><li><strong>评估成本</strong></li><li><strong>失效成本</strong></li></ul><h2 id="软件评审" tabindex="-1">软件评审 <a class="header-anchor" href="#软件评审" aria-label="Permalink to &quot;软件评审&quot;">​</a></h2><ul><li><strong>非正式评审</strong>：与同事进行的简单桌面检查、临时会议或结对编程评审。</li><li><strong>正式技术评审 (FTR)</strong>：包括走查 (walkthrough) 和审查 (inspection)。</li></ul><h2 id="软件测试" tabindex="-1">软件测试 <a class="header-anchor" href="#软件测试" aria-label="Permalink to &quot;软件测试&quot;">​</a></h2><p><strong>目的</strong>：发现软件设计和实现过程中因疏忽所造成的错误。</p><p><img src="'+p+'" alt="alt text"><img src="'+b+'" alt="alt text"></p><h3 id="白盒测试" tabindex="-1">白盒测试 <a class="header-anchor" href="#白盒测试" aria-label="Permalink to &quot;白盒测试&quot;">​</a></h3><p>也称为玻璃盒测试或结构化测试。利用控制结构来生成测试用例。</p><p><strong>目标</strong>：</p><ol><li>保证一个模块中的所有独立路径至少被执行一次</li><li>对所有的逻辑判定均需测试取真和取假两个方面</li><li>在上下边界及可操作的范围内执行所有循环</li><li>检验内部数据结构以确保其有效性</li></ol><p><strong>基本路径测试</strong>：由 Tom McCabe 提出。计算过程设计的逻辑复杂性，定义执行路径的基本集，保证程序中的每一条语句至少执行一次。</p><h3 id="黑盒测试" tabindex="-1">黑盒测试 <a class="header-anchor" href="#黑盒测试" aria-label="Permalink to &quot;黑盒测试&quot;">​</a></h3><p>也称行为测试或功能测试，侧重于软件的功能需求。不是白盒测试的替代品，而是辅助方法。</p><p><strong>等价类划分</strong>：将程序的输入划分为若干个数据类，从中生成测试用例。</p><h3 id="集成测试" tabindex="-1">集成测试 <a class="header-anchor" href="#集成测试" aria-label="Permalink to &quot;集成测试&quot;">​</a></h3><ul><li><strong>增量集成</strong>：与“一步到位”的集成方法相反。</li><li><strong>面向对象系统的集成策略</strong>：基于线程的测试、基于使用的测试。</li></ul><h2 id="项目管理" tabindex="-1">项目管理 <a class="header-anchor" href="#项目管理" aria-label="Permalink to &quot;项目管理&quot;">​</a></h2><p><strong>范围 (4P)</strong>：</p><ul><li><strong>人员 (People)</strong></li><li><strong>产品 (Product)</strong></li><li><strong>过程 (Process)</strong></li><li><strong>项目 (Project)</strong></li></ul>',115)]))}const A=a(q,[["render",x]]);export{B as __pageData,A as default};
